CREATE TABLE STUDENTS (STUDENT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NAME VARCHAR2(120) NOT NULL, REGISTER_NUMBER VARCHAR2(40) NOT NULL UNIQUE, DEPARTMENT VARCHAR2(100) NOT NULL, YEAR_LEVEL VARCHAR2(10) NOT NULL, EMAIL VARCHAR2(180) NOT NULL UNIQUE, PASSWORD_HASH VARCHAR2(100) NOT NULL, CONTACT_NUMBER VARCHAR2(30), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE OFFICIALS (OFFICIAL_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NAME VARCHAR2(120) NOT NULL, EMPLOYEE_ID VARCHAR2(40) NOT NULL UNIQUE, EMAIL VARCHAR2(180) NOT NULL UNIQUE, PASSWORD_HASH VARCHAR2(100) NOT NULL, CONTACT_NUMBER VARCHAR2(30), DESIGNATION VARCHAR2(60) NOT NULL, DEPARTMENT VARCHAR2(100) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE APPOINTMENTS (APPOINTMENT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STUDENT_ID NUMBER NOT NULL REFERENCES STUDENTS(STUDENT_ID), OFFICIAL_ID NUMBER NOT NULL REFERENCES OFFICIALS(OFFICIAL_ID), PURPOSE VARCHAR2(150) NOT NULL, DESCRIPTION VARCHAR2(2000), REQUESTED_DATE DATE NOT NULL, PREFERRED_TIME TIMESTAMP NOT NULL, ALLOCATED_DATE DATE, ALLOCATED_TIME TIMESTAMP, STATUS VARCHAR2(20) DEFAULT 'PENDING' NOT NULL CHECK (STATUS IN ('PENDING','APPROVED','REJECTED','CANCELLED','COMPLETED')), REMARKS VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE NOTIFICATIONS (NOTIFICATION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, USER_ID NUMBER NOT NULL, USER_ROLE VARCHAR2(15) NOT NULL CHECK (USER_ROLE IN ('student','official')), TITLE VARCHAR2(200) NOT NULL, MESSAGE VARCHAR2(2000) NOT NULL, TYPE VARCHAR2(40), IS_READ NUMBER(1) DEFAULT 0 NOT NULL CHECK (IS_READ IN (0,1)), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE AVAILABILITY (AVAILABILITY_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, OFFICIAL_ID NUMBER NOT NULL REFERENCES OFFICIALS(OFFICIAL_ID), DAY_NAME VARCHAR2(12) NOT NULL, START_TIME VARCHAR2(8), END_TIME VARCHAR2(8), IS_AVAILABLE NUMBER(1) DEFAULT 1 NOT NULL CHECK (IS_AVAILABLE IN (0,1)), CONSTRAINT UK_AVAILABILITY_DAY UNIQUE (OFFICIAL_ID, DAY_NAME));
CREATE INDEX IDX_APPOINTMENTS_STUDENT ON APPOINTMENTS(STUDENT_ID, CREATED_AT); CREATE INDEX IDX_APPOINTMENTS_OFFICIAL ON APPOINTMENTS(OFFICIAL_ID, STATUS); CREATE INDEX IDX_NOTIFICATIONS_USER ON NOTIFICATIONS(USER_ID, CREATED_AT);
